import numpy as np,json,glob
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares

def trans(rot,p):
 T=np.eye(4);T[:3,:3]=R.from_rotvec(rot).as_matrix();T[:3,3]=p;return T

def fk(q):
 T=np.eye(4)
 for qi,a,d,alpha in zip(q,[0,0,0,.0825,-.0825,0,.088],[.333,0,.316,0,.384,0,0],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
  c,s=np.cos(qi),np.sin(qi);ca,sa=np.cos(alpha),np.sin(alpha)
  T=T@np.array([[c,-s,0,a],[s*ca,c*ca,-sa,-d*sa],[s*sa,c*sa,ca,d*ca],[0,0,0,1]])
 return T

def data(path):
 m=json.load(open(path+'/meta.json'));p=np.array(m['proprio']['now']);C=np.array(m['cameras']['robot0_eye_in_hand']['cam2world_gl']);return p[4:11],C,p[26:29]

def fit():
 ds=[data(p) for p in sorted(glob.glob('/app/runs/cal_*'))]
 if len(ds)<8:print('not ready',len(ds));return
 F=[fk(q) for q,c,p in ds]
 C0=ds[0][1];E0=np.linalg.inv(F[0])@C0
 x0=np.r_[np.zeros(6),R.from_matrix(E0[:3,:3]).as_rotvec(),E0[:3,3]]
 def residual(x):
  B=trans(x[:3],x[3:6]);E=trans(x[6:9],x[9:12]);rs=[]
  for f,(q,c,p) in zip(F,ds):
   pred=B@f@E
   rs.extend((pred[:3,3]-c[:3,3]));rs.extend(R.from_matrix(pred[:3,:3]@c[:3,:3].T).as_rotvec())
  return rs
 sol=least_squares(residual,x0,max_nfev=1500,xtol=1e-13,ftol=1e-13,gtol=1e-13)
 B=trans(sol.x[:3],sol.x[3:6]);E=trans(sol.x[6:9],sol.x[9:12]);cp=np.mean([c[:3,:3].T@(p-c[:3,3]) for q,c,p in ds],axis=0)
 print('rms',np.sqrt(np.mean(np.array(residual(sol.x))**2)),'max',np.max(np.abs(residual(sol.x))));print('B',B,'E',E,'cp',cp)
 np.savez('/app/output/kin.npz',B=B,E=E,cp=cp)

class Kin:
 def __init__(self):
  a=np.load('/app/output/kin.npz');self.B=a['B'];self.E=a['E'];self.cp=a['cp']
 def camera(self,q):return self.B@fk(q)@self.E
 def ee(self,q):
  c=self.camera(q);return c[:3,3]+c[:3,:3]@self.cp
 def ik(self,pos,rot,q0):
  def res(q):
   c=self.camera(q);return np.r_[(self.ee(q)-pos)*5,R.from_matrix(c[:3,:3]@rot.T).as_rotvec(),.015*(q-q0)]
  sol=least_squares(res,q0,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.017,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=300)
  print('IK',sol.x,'ee',self.ee(sol.x),'error',res(sol.x)[:6]);return sol.x
if __name__=='__main__':fit()
PY

